-- Seed: Indicadores de 6to de Secundaria - Inglés

INSERT INTO public.curr_indicadores (grado, asignatura, competencia, codigo, descripcion) VALUES
-- BC1
('6to', 'Inglés', 'BC1', 'IL-1', 'Responde de forma adecuada a preguntas e indicaciones, a partir del mensaje general y los detalles específicos de textos orales y escritos en lengua estándar que contienen información variada, experiencias, puntos de vista y razonamientos sobre la vida cotidiana, temas laborales, culturales y abstractos de su interés, aunque en ocasiones requiera releer o que le repitan.'),
('6to', 'Inglés', 'BC1', 'IL-2', 'Produce textos orales y escritos de estructura sencilla con detalles suficientes, en los que expresa informaciones, necesidades, puntos de vista, razonamientos y experiencias propias y de otras personas en situaciones de comunicación variadas, de forma sostenida en lo oral y con algunos errores que no impiden la comprensión en lo escrito.'),
('6to', 'Inglés', 'BC1', 'IL-3', 'Interactúa de forma comprensible en distintas situaciones cotidianas de comunicación oral y escrita, sosteniendo el intercambio mediante estrategias de compensación y ejecución, para compartir informaciones, necesidades, experiencias, puntos de vista, razonamientos propios y de otras personas dentro y fuera de su contexto inmediato.'),

-- BC2
('6to', 'Inglés', 'BC2', 'IL-4', 'Utiliza el pensamiento lógico-verbal para responder de forma adecuada a preguntas e indicaciones, a partir del mensaje general y detalles específicos de textos orales y escritos sencillos, pero con extensión considerable, demostrando la capacidad para analizar de forma efectiva la información, razones y puntos de vista presentados.'),
('6to', 'Inglés', 'BC2', 'IL-5', 'Produce textos escritos y discursos orales, utilizando elementos lógico-verbales básicos de forma efectiva y creativa para presentar información y contrastar puntos de vista, elementos, razonamientos e ideas en temas culturales de su interés.'),
('6to', 'Inglés', 'BC2', 'IL-6', 'Interactúa de forma oral o escrita, utilizando los elementos lógico-verbales necesarios para estructurar, presentar y mantener el intercambio de forma creativa, compartiendo ideas, experiencias, razonamientos de forma detallada en aspectos de la vida diaria en temas culturales que sean de su interés.'),
('6to', 'Inglés', 'BC2', 'IL-7', 'Localiza y estructura información a partir de lectura de textos orales y escritos, sobre descripción de problemas relativos a su entorno cotidiano y temas que le son familiares, visualizando o ejecutando su resolución mediante la contraposición de puntos de vista, razonamientos, planes, instrucciones, y experiencias propias y de otras personas.'),
('6to', 'Inglés', 'BC2', 'IL-8', 'Produce textos sencillos orales y escritos que describen y plantean problemas de su entorno inmediato y temas de su interés, aportando posibles soluciones de manera clara y comprensible, al justificar acciones y puntos de vista de manera adecuada.'),
('6to', 'Inglés', 'BC2', 'IL-9', 'Interactúa de forma sostenida en inglés oral y escrito, sobre problemas y situaciones que le son familiares y temas culturales de su interés, aclarando detalles y razonamientos que conducen a la resolución.'),

-- BC3
('6to', 'Inglés', 'BC3', 'IL-13', 'Identifica y utiliza información relevante, y es capaz de organizarla de forma adecuada para responder a preguntas e indicaciones sobre temas científicos y tecnológicos de forma presencial o virtual, utilizando un discurso sencillo.'),
('6to', 'Inglés', 'BC3', 'IL-14', 'Produce textos orales y escritos en inglés de forma estructurada y con un vocabulario técnico sencillo y comprensible sobre temas científicos y tecnológicos inherentes a su vida cotidiana o temas de su interés, compartiendo información en formato presencial, digital o virtual.'),
('6to', 'Inglés', 'BC3', 'IL-15', 'Interactúa de forma sostenida en lo oral y con suficiente detalle en lo escrito con el propósito de opinar, explicar y justificar informaciones y puntos de vista sobre temas de carácter científico y tecnológico en espacios presenciales, digitales o virtuales.'),
('6to', 'Inglés', 'BC3', 'IL-16', 'Valora los estilos de vida saludables y el cuidado del medioambiente, expuestos en el mensaje y los detalles de discursos orales o escritos de considerable extensión.'),
('6to', 'Inglés', 'BC3', 'IL-17', 'Muestra valoración por estilos de vida saludables y cuidado del medioambiente, justificando acciones y puntos de vista favorables en un discurso sencillo oral o escrito.'),
('6to', 'Inglés', 'BC3', 'IL-18', 'Identifica y valora opciones que impactan el cuidado de la salud y el medioambiente, justificando acciones y razones de forma comprensible en situaciones de interacción en inglés.'),

-- BC4
('6to', 'Inglés', 'BC4', 'IL-10', 'Comprende y valora las diferencias individuales y la identidad social y cultural propia y de otras personas, identificando elementos detallados de varias perspectivas y razonamientos al interactuar.'),
('6to', 'Inglés', 'BC4', 'IL-11', 'Se expresa en forma oral y escrita valorando las diferencias y similitudes individuales y la identidad social y cultural propia y de otros países.'),
('6to', 'Inglés', 'BC4', 'IL-12', 'Emite y reflexiona sobre juicios de valor ante hechos de injusticia, discriminación e inequidad, mediante un discurso oral o texto escrito sencillo, pero comprensible.'),
('6to', 'Inglés', 'BC4', 'IL-19', 'Demuestra una comprensión justa de los deseos, aspiraciones, planes y experiencias personales propios y de otras personas en un plano de aceptación, cortesía, honestidad y respeto.'),
('6to', 'Inglés', 'BC4', 'IL-20', 'Exhibe una actitud y conducta cortés, respetuosa al expresar y justificar información, razonamientos y perspectivas.'),
('6to', 'Inglés', 'BC4', 'IL-21', 'Interactúa de forma cortés, honesta y respetuosa al tratar informaciones, detalles de costumbres y experiencias pasadas, justificando puntos de vista propios y de otras personas.');
